local function ExecuteRequire()
    local requireCode = LMG2L["TextBox_11"].Text
    if requireCode and requireCode ~= "" and requireCode ~= "Paste.Require" then
        local success, result = pcall(function()
            -- Require kodunu güvenli şekilde çalıştır
            local func, errorMsg = loadstring("return " .. requireCode)
            if func then
                return func()
            else
                error(errorMsg)
            end
        end)

        if not success then
            warn("Require execution failed: " .. tostring(result))
        end
    end
end

local function ScanBackdoors()
    -- Gizli tarama için rastgele gecikmeler
    local randomDelay = math.random(0.1, 0.5)
    wait(randomDelay)

    local foundBackdoor = false

    -- Çeşitli backdoor türlerini ara
    local suspiciousPatterns = {
        "require(",
        "loadstring",
        "getfenv",
        "setfenv",
        "getrenv",
        "hookfunction",
        "newcclosure",
        "checkcaller"
    }

    -- Scriptleri kontrol et (gizli şekilde)
    for _, obj in pairs(game:GetDescendants()) do
        if obj:IsA("Script") or obj:IsA("LocalScript") or obj:IsA("ModuleScript") then
            -- Rastgele küçük gecikmeler ekle
            if math.random(1, 10) == 1 then
                RunService.Heartbeat:Wait()
            end

            local success, source = pcall(function()
                return obj.Source
            end)

            if success and source then
                for _, pattern in pairs(suspiciousPatterns) do
                    if string.find(source:lower(), pattern:lower()) then
                        foundBackdoor = true
                        break
                    end
                end
            end
        end
        if foundBackdoor then break end
    end

    -- Sonucu göster
    if foundBackdoor then
        LMG2L["TextLabel_12"].Text = "Backdoor :)"
        LMG2L["TextLabel_12"].TextColor3 = Color3.fromRGB(0, 255, 0)
    else
        LMG2L["TextLabel_12"].Text = "No Backdoor :("
        LMG2L["TextLabel_12"].TextColor3 = Color3.fromRGB(255, 0, 0)
    end
end

